urlset:
{{~ for url in urls ~}}

  {{ url.loc | string.replace (site.basepath + site.basepath) site.basepath }}
  {{~ if url.lastmod ~}}
  {{ url.lastmod }}
  {{~ end ~}}
  {{~ if url.changefreq ~}}
  {{ url.changefreq }}
  {{~ end ~}}
  {{~ if url.priority ~}}
  {{ url.priority }}
  {{~ end ~}}

{{~ end ~}}
